// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor } from "./actors.js";
import { applyOneStep, beginAdvancementSession, commitAdvancementManager, getAdvancementManagerClass } from "./advancement.js";
import { nativeCompendiumSearch, parseCompendiumSearchQuery, spotlightCompendiumSearch } from "./compendium.js";
import { CHARACTER_IMAGE_MAX_LONG_SIDE, MODULE_ID } from "./constants.js";
