import { bridgeFlag, clearBridgeFlagsUpdate } from "./flags.js";
// Character + homebrew content creation (race/class/background/feat/subclass) — extracted from mobile-bridge.js.

export function actorIsUnderConstruction(actor) {
  return bridgeFlag(actor, "creating") === true;
}

/**
 * Writes the six ability scores.
 *
 * Rolling up a character means setting these, and the player doing it is a
 * plain player by definition. Afterwards the same edit belongs to the sheet,
 * where it is a Trusted matter - so the permission lasts exactly as long as the
 * character is under construction.
 */
export async function actorAbilitiesSet(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  if (!actorIsUnderConstruction(actor) && (user.role ?? 0) < CONST.USER_ROLES.TRUSTED) {
    throw new Error("Editing ability scores requires Trusted Player role");
  }
  const scores = payload?.abilities ?? {};
  const update = {};
  for (const key of Object.keys(CONFIG.DND5E?.abilities ?? {})) {
    const raw = Number(scores[key]);
    if (!Number.isFinite(raw)) continue;
    update[`system.abilities.${key}.value`] = Math.max(1, Math.min(Math.round(raw), 30));
  }
  if (!Object.keys(update).length) throw new Error("No ability scores given");
  await actor.update(update);
  const summary = Object.keys(CONFIG.DND5E?.abilities ?? {})
    .filter((key) => `system.abilities.${key}.value` in update)
    .map((key) => `${abilityLabelFor(key)} ${update[`system.abilities.${key}.value`]}`)
    .join(", ");
  await logDirectChange(actor, user, `Ability scores: ${summary}`);
  return { accepted: true, actorId: actor.id };
}

/**
 * Deletes a character the requesting user owns.
 *
 * Ownership is the whole check: a player may throw away their own character,
 * and `getOwnedActor` will not hand over anyone else's. It cannot be undone, so
 * the GM is told which character went and who deleted it.
 */
export async function deleteOwnedActor(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const name = actor.name;
  await announceCharacterDeleted(user, name);
  await actor.delete();
  console.log(`[${MODULE_ID}] ${user.name} deleted character "${name}"`);
  return { deleted: true, name };
}

export async function announceCharacterDeleted(user, name) {
  try {
    const gmIds = game.users.filter((u) => u.isGM).map((u) => u.id);
    if (!gmIds.length) return;
    await ChatMessage.create({
      content: `<p>${journalStrings().characterDeleted(escapeLogHtml(user.name), escapeLogHtml(name))}</p>`,
      whisper: gmIds
    });
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not announce character deletion`, err);
  }
}

/**
 * Renames a character.
 *
 * Going back to the first step of the creation wizard has to be able to change
 * the name, and by then the actor exists. Bounded the same way ability scores
 * are: anyone may while the character is a draft, Trusted afterwards.
 */
export async function actorRename(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  if (!actorIsUnderConstruction(actor) && (user.role ?? 0) < CONST.USER_ROLES.TRUSTED) {
    throw new Error("Renaming a character requires Trusted Player role");
  }
  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("name is required");
  if (name.length > 100) throw new Error("name is too long");
  await actor.update({ name });
  if (actorIsUnderConstruction(actor)) await logDirectChange(actor, user, `Name: ${name}`);
  return { accepted: true, actorId: actor.id, name };
}

/**
 * Takes back what a creation step applied, so it can be answered again.
 *
 * Only while the character is still a draft: the same call against a finished
 * character would be a way to strip it.
 */
export async function creationStepBack(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  if (!actorIsUnderConstruction(actor)) {
    throw new Error("This character is no longer being created");
  }
  const step = String(payload?.step ?? "");
  let result;
  switch (step) {
    case "race": result = await removeItemsOfType(actor, raceItemType()); break;
    case "background": result = await removeItemsOfType(actor, "background"); break;
    case "class": result = await removeClassAndItsGrants(actor); break;
    case "equipment": result = await revokeStartingEquipment(actor); break;
    default: result = { removed: 0 };
  }
  if (step) await logDirectChange(actor, user, `Undid creation step: ${step}`);
  return result;
}

export async function removeItemsOfType(actor, type) {
  const ids = actor.items.filter((item) => item.type === type).map((item) => item.id);
  if (ids.length) await actor.deleteEmbeddedDocuments("Item", ids);
  return { removed: ids.length };
}

/**
 * Removes the class along with everything its advancement handed out.
 *
 * Deleting the item alone would leave the granted features behind, orphaned and
 * invisible to the next class the player picks — so dnd5e unwinds it, through
 * the same manager the sheet uses when a class is dragged off.
 */
export async function removeClassAndItsGrants(actor) {
  const classItem = actor.items.find((item) => item.type === "class");
  if (!classItem) return { removed: 0 };
  const Manager = getAdvancementManagerClass();
  const manager = Manager.forDeletedItem(actor, classItem.id);
  if (!manager?.steps?.length) {
    await actor.deleteEmbeddedDocuments("Item", [classItem.id]);
    return { removed: 1 };
  }
  // Every step of a deletion manager is a reversal; none of them asks anything.
  const session = { manager, stepIndex: 0 };
  while (session.stepIndex < manager.steps.length) {
    await applyOneStep(session, manager.steps[session.stepIndex], undefined);
    session.stepIndex++;
  }
  await commitAdvancementManager(manager);
  return { removed: 1 };
}

/** Takes back the items the equipment step created, and the gold it rolled. */
export async function revokeStartingEquipment(actor) {
  const ids = actor.items
    .filter((item) => bridgeFlag(item, "creationEquipment") === true)
    .map((item) => item.id);
  if (ids.length) await actor.deleteEmbeddedDocuments("Item", ids);

  const wealth = Number(bridgeFlag(actor, "creationWealth")) || 0;
  if (wealth > 0) {
    const key = CONFIG.DND5E?.defaultCurrency ?? "gp";
    const current = Number(foundry.utils.getProperty(actor, `system.currency.${key}`)) || 0;
    await actor.update({
      [`system.currency.${key}`]: Math.max(0, current - wealth),
      ...clearBridgeFlagsUpdate(actor, ["creationWealth"])
    });
  }
  return { removed: ids.length, wealth };
}

/** Ends the wizard: the character stops being a work in progress. */
export async function finishCharacterCreation(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  await actor.update(clearBridgeFlagsUpdate(actor, ["creating"]));
  await logDirectChange(actor, user, "Character creation finished");
  return { accepted: true, actorId: actor.id };
}

/** dnd5e has renamed its ancestry item between versions - ask, do not guess. */
export function raceItemType() {
  const types = game.documentTypes?.Item ?? game.system?.documentTypes?.Item ?? [];
  if (types.includes?.("race")) return "race";
  if (types.includes?.("species")) return "species";
  return "race";
}

/**
 * Item data for an origin choice.
 *
 * From a compendium it is the document itself, advancement table and all. Typed
 * by hand it is a bare item carrying only a name: a player writing their own
 * race or class has no table for us to invent, and inventing one would be worse
 * than leaving it empty.
 */
export async function originItemData({ uuid, name, type }) {
  if (uuid) {
    const doc = await fromUuid(String(uuid));
    if (!doc) throw new Error(`Compendium entry not found: ${uuid}`);
    if (doc.documentName !== "Item") throw new Error("Compendium entry is not an Item");
    if (doc.type !== type) throw new Error(`Expected a ${type}, got ${doc.type}`);
    return doc.toObject();
  }
  const trimmed = String(name ?? "").trim();
  if (!trimmed) throw new Error("name or uuid is required");
  if (trimmed.length > 100) throw new Error("name is too long");
  return { name: trimmed, type };
}

/**
 * Puts an origin item on an actor, running its advancement when it has any.
 *
 * Races, backgrounds and classes all carry advancement in current dnd5e — a
 * background can grant an ability bonus or a feat exactly as a class grants hit
 * points — so all three go through the same door rather than only the class.
 */
export async function attachOriginItem(user, actor, data, { replaceType = null, viaCompendium = false }) {
  if (replaceType) {
    const previous = actor.items.filter((item) => item.type === replaceType).map((item) => item.id);
    if (previous.length) await actor.deleteEmbeddedDocuments("Item", previous);
  }
  if (viaCompendium) {
    const Manager = getAdvancementManagerClass();
    const manager = Manager.forNewItem(actor, data);
    if (manager?.steps?.length) {
      const view = await beginAdvancementSession(user, actor, manager, `${data.type}=${data.name}`, {
        creation: true
      });
      return { ...view, needsAdvancement: true, name: data.name };
    }
  }
  const [created] = await actor.createEmbeddedDocuments("Item", [data]);
  return { needsAdvancement: false, itemId: created?.id ?? null, name: created?.name ?? null };
}

/** Sets the actor's race, replacing whatever was there. */
export async function actorRaceSet(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const type = raceItemType();
  const data = await originItemData({ uuid: payload?.uuid, name: payload?.name, type });
  const result = await attachOriginItem(user, actor, data, {
    replaceType: type,
    viaCompendium: !!payload?.uuid
  });
  await logDirectChange(actor, user, `Race: ${result.name ?? data.name}`);
  return { ...result, type };
}

/** Sets the actor's background, replacing whatever was there. */
export async function actorBackgroundSet(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const data = await originItemData({
    uuid: payload?.uuid,
    name: payload?.name,
    type: "background"
  });
  const result = await attachOriginItem(user, actor, data, {
    replaceType: "background",
    viaCompendium: !!payload?.uuid
  });
  await logDirectChange(actor, user, `Background: ${result.name ?? data.name}`);
  return { ...result, type: "background" };
}

/* ------------------------------------------------------------------ *
 * Starting equipment
 * ------------------------------------------------------------------ */

/**
 * The starting equipment offered by everything the character has taken so far.
 *
 * dnd5e stores this as a tree of entries — AND groups that all apply, OR groups
 * the player chooses between — but grants none of it: the system has an editor
 * for the list and no code that hands it out, so the choosing and the granting
 * are both ours to do.
 *
 * Only `linked` entries name an actual item. A category entry ("any martial
 * weapon") is reported with its label and no uuid, because resolving it means
 * asking a question this step does not ask.
 */
export function startingEquipmentFor(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const sources = [];
  for (const item of actor.items) {
    if (!["class", "background"].includes(item.type)) continue;
    const entries = item.system?.startingEquipment ?? [];
    if (!entries.length && !item.system?.wealth) continue;
    const childrenOf = (groupId) => entries
      .filter((entry) => (entry.group ?? null) === groupId)
      .sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0))
      .map(describeEquipmentEntry);

    function describeEquipmentEntry(entry) {
      let label = "";
      try {
        label = entry.generateLabel?.() ?? "";
      } catch (err) {
        console.warn(`[${MODULE_ID}] equipment label failed`, err);
      }
      return {
        id: entry._id,
        type: entry.type,
        label: String(label).replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(),
        count: Number(entry.count) || 1,
        uuid: entry.type === "linked" ? (entry.key ?? null) : null,
        children: childrenOf(entry._id)
      };
    }

    sources.push({
      itemId: item.id,
      itemName: item.name,
      itemType: item.type,
      wealth: String(item.system?.wealth ?? ""),
      // Gold granted alongside the item package (module flag; see backgroundCreate).
      insetCurrency: String(bridgeFlag(item, "startingEquipmentCurrency") ?? ""),
      entries: childrenOf(null)
    });
  }
  return { sources };
}

/**
 * Creates the chosen items on the actor and rolls any starting wealth.
 *
 * The uuids are checked against what the character's own class and background
 * actually offer, so the list the phone sends back can only ever be a subset of
 * what it was shown.
 */
export async function grantStartingEquipment(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const offered = new Set();
  const collect = (entries) => {
    for (const entry of entries) {
      if (entry.uuid) offered.add(entry.uuid);
      collect(entry.children ?? []);
    }
  };
  const available = startingEquipmentFor(user, payload);
  for (const source of available.sources) collect(source.entries);

  const wanted = Array.isArray(payload?.uuids) ? payload.uuids.map(String) : [];
  const granted = [];
  for (const uuid of wanted) {
    if (!offered.has(uuid)) {
      console.warn(`[${MODULE_ID}] refusing equipment not offered to this character: ${uuid}`);
      continue;
    }
    const doc = await fromUuid(uuid);
    if (!doc || doc.documentName !== "Item") continue;
    const data = doc.toObject();
    const count = Number(payload?.counts?.[uuid]) || 1;
    if (count > 1) foundry.utils.setProperty(data, "system.quantity", count);
    // Marked so stepping back can take exactly these away again, without
    // guessing which of the character's possessions came from this step.
    foundry.utils.setProperty(data, `flags.${MODULE_ID}.creationEquipment`, true);
    granted.push(data);
  }
  if (granted.length) {
    await actor.createEmbeddedDocuments("Item", granted);
    const names = granted.map((d) => d.name).filter(Boolean).join(", ");
    if (names) await logDirectChange(actor, user, `Starting equipment: ${names}`);
  }

  // Gold, per source: if the player takes that source's "gold instead"
  // alternative (rollWealth) its `wealth` formula is rolled; otherwise the gold
  // that comes with the package (`insetCurrency`) is granted. The two are the
  // mutually exclusive halves of "option A (items + gold) or option B (gold)".
  let wealth = 0;
  const key = CONFIG.DND5E?.defaultCurrency ?? "gp";
  for (const source of available.sources) {
    const takingWealth = payload?.rollWealth === true && source.wealth;
    const formula = takingWealth ? source.wealth : (source.insetCurrency || "");
    if (!formula) continue;
    try {
      const roll = await new Roll(String(formula)).evaluate();
      wealth += Number(roll.total) || 0;
    } catch (err) {
      console.warn(`[${MODULE_ID}] starting-gold formula failed: ${formula}`, err);
    }
  }
  if (wealth > 0) {
    const current = Number(foundry.utils.getProperty(actor, `system.currency.${key}`)) || 0;
    await actor.update({
      [`system.currency.${key}`]: current + wealth,
      [`flags.${MODULE_ID}.creationWealth`]: wealth
    });
    await logDirectChange(actor, user, `Starting gold: ${wealth} ${key}`);
  }
  return { grantedCount: granted.length, wealth };
}



/**
 * Gives a character its first class.
 *
 * A class from a compendium goes through the same advancement wizard the
 * level-up flow uses, so hit points, skills and starting features are chosen
 * rather than guessed. A class typed by hand has no advancement to walk and
 * simply goes on.
 *
 * Only the *first* class: adding another is levelling, which stays behind the
 * Trusted gate rather than riding in on the creation screen.
 */
export async function actorClassAdd(user, payload) {
  const actor = getOwnedActor(user, payload?.actorId);
  const existing = actor.items.filter((item) => item.type === "class");
  if (existing.length && (user.role ?? 0) < CONST.USER_ROLES.TRUSTED) {
    throw new Error("This character already has a class");
  }

  const data = await originItemData({ uuid: payload?.uuid, name: payload?.name, type: "class" });
  foundry.utils.setProperty(data, "system.levels", 1);

  if (payload?.uuid) {
    const Manager = getAdvancementManagerClass();
    const manager = Manager.forNewItem(actor, data);
    if (manager?.steps?.length) {
      const view = await beginAdvancementSession(user, actor, manager, `class=${data.name}`, {
        creation: true
      });
      await logDirectChange(actor, user, `Class: ${data.name}`);
      return { ...view, needsAdvancement: true };
    }
  }

  const [created] = await actor.createEmbeddedDocuments("Item", [data]);
  await logDirectChange(actor, user, `Class: ${created?.name ?? data.name}`);
  return { itemId: created?.id ?? null, name: created?.name ?? null, needsAdvancement: false };
}

/**
 * Creates an empty player character owned by the requesting user.
 *
 * Foundry does not let a player create actors; this runs on the GM's client, so
 * that check never applies and the module has to be the one drawing the line.
 * The line here is deliberately generous — a table starting a campaign wants
 * everyone making their own character — so the GM is told each time instead.
 */
/**
 * The Actor-directory folder that holds a player's characters, named after the
 * player and created the first time one of their characters is made. Keeps every
 * player's phone-made characters together instead of loose in the sidebar.
 * Best-effort: if the folder cannot be made, the character is still created at
 * the directory root.
 */
export async function ensurePlayerActorFolder(user) {
  const name = String(user?.name ?? "").trim();
  if (!name) return null;
  const existing = game.folders?.find(
    (folder) => folder.type === "Actor" && folder.name === name
  );
  if (existing) return existing;
  try {
    return await Folder.create({ name, type: "Actor", sorting: "a" });
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not create player actor folder "${name}"`, err);
    return null;
  }
}

export async function createCharacterActor(user, payload) {
  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("name is required");
  if (name.length > 100) throw new Error("name is too long");

  const levels = CONST.DOCUMENT_OWNERSHIP_LEVELS;
  const documentClass = CONFIG.Actor.documentClass;
  const folder = await ensurePlayerActorFolder(user);
  const actor = await documentClass.create({
    name,
    type: "character",
    folder: folder?.id ?? null,
    ownership: { default: levels.NONE, [user.id]: levels.OWNER },
    // A character's token has to follow its sheet; an unlinked copy would drift
    // away from the actor the phone is editing.
    prototypeToken: {
      actorLink: true,
      disposition: CONST.TOKEN_DISPOSITIONS.FRIENDLY,
      sight: { enabled: true }
    },
    // Marks the character as still being made. Some steps let a plain player
    // write things the sheet would otherwise reserve for a Trusted one, and
    // this is what bounds that permission to the wizard instead of granting it
    // for good.
    [`flags.${MODULE_ID}.creating`]: true
  });
  if (!actor) throw new Error("Actor creation failed");
  // Fallback: if the folder did not take at create time, move it in now.
  const folderAfterCreate = actor.folder?.id ?? actor.folder ?? null;
  if (folder?.id && folderAfterCreate !== folder.id) {
    try {
      await actor.update({ folder: folder.id });
    } catch (err) {
      console.warn(`[${MODULE_ID}] could not move character into folder`, err);
    }
  }

  await announceCharacterCreated(user, actor);
  console.log(`[${MODULE_ID}] ${user.name} created character "${actor.name}" (${actor.id})`);
  return { actorId: actor.id, name: actor.name };
}

/** A new actor appearing in the sidebar unannounced is a mystery to the GM. */
export async function announceCharacterCreated(user, actor) {
  try {
    const gmIds = game.users.filter((u) => u.isGM).map((u) => u.id);
    if (!gmIds.length) return;
    await ChatMessage.create({
      content: `<p>${journalStrings().characterCreated(escapeLogHtml(user.name), escapeLogHtml(actor.name))}</p>`,
      whisper: gmIds
    });
  } catch (err) {
    console.warn(`[${MODULE_ID}] could not announce character creation`, err);
  }
}

/* ------------------------------------------------------------------ *
 * Background authoring wizard
 *
 * A dnd5e background is a thin item: its substance lives in its advancements
 * (ability-score points, skill/tool/language proficiencies, an origin feat)
 * plus a starting-equipment tree. The phone gathers those parameters and this
 * assembles the item — a reusable world item any player may author, logged for
 * the GM, and deliberately never applied to a sheet on its own.
 * ------------------------------------------------------------------ */

/** Equipment entry types dnd5e understands (grouping + option kinds). */
export const EQUIPMENT_ENTRY_TYPES = new Set(["AND", "OR", "armor", "tool", "weapon", "focus", "linked"]);

/** dnd5e's Trait helper namespace, or null on an unexpected build. */
export function traitHelper() {
  return game?.dnd5e?.documents?.Trait ?? null;
}

/** Current rules edition ("modern" = 2024, "legacy" = 2014). */
export function currentRulesVersion() {
  const fromSettings = () => {
    try { return game.settings.get("dnd5e", "rulesVersion"); } catch (err) { return null; }
  };
  return game?.dnd5e?.settings?.rulesVersion
    ?? CONFIG?.DND5E?.rulesVersion
    ?? fromSettings()
    ?? "modern";
}

/**
 * Flatten a dnd5e SelectChoices tree into flat rows the phone renders, keeping
 * the category nesting through `depth`. A category ("Artisan's Tools") is a
 * heading the player groups under, not a pick, so it is marked unselectable.
 */
export function flattenSelectChoices(choices) {
  const rows = [];
  const walk = (node, depth) => {
    for (const [key, data] of Object.entries(node ?? {})) {
      if (!data || typeof data !== "object") continue;
      const isCategory = !!data.category || !!data.children;
      rows.push({
        key,
        label: String(data.label ?? key),
        selectable: data.selectable !== false && !isCategory,
        depth
      });
      if (data.children) walk(data.children, depth + 1);
    }
  };
  walk(choices, 0);
  return rows;
}

/** Selectable keys + labels for one trait type ("skills"/"tool"/"languages"). */
export async function traitChoiceRows(traitType) {
  const Trait = traitHelper();
  if (typeof Trait?.choices !== "function") return [];
  try {
    const choices = await Trait.choices(traitType, { prefixed: true });
    return flattenSelectChoices(choices);
  } catch (err) {
    console.warn(`[${MODULE_ID}] trait choices failed for ${traitType}`, err);
    return [];
  }
}

/** Reference data the background wizard needs to build its pickers. */
export async function backgroundMeta() {
  const localize = (label, fallback) => {
    const raw = (typeof label === "string" ? label : label?.label) ?? fallback;
    return raw ? game.i18n.localize(raw) : String(fallback ?? "");
  };
  const abilities = Object.entries(CONFIG.DND5E?.abilities ?? {}).map(([id, cfg]) => ({
    id,
    label: localize(cfg?.label, id)
  }));
  const [skills, tools, languages] = await Promise.all([
    traitChoiceRows("skills"),
    traitChoiceRows("tool"),
    traitChoiceRows("languages")
  ]);
  const cfgList = (obj) => Object.entries(obj ?? {}).map(([id, cfg]) => ({
    id,
    label: localize(cfg, id)
  }));
  return {
    rulesVersion: currentRulesVersion(),
    abilities,
    skills,
    tools,
    languages,
    equipment: {
      armor: cfgList(CONFIG.DND5E?.armorTypes),
      weapon: cfgList(CONFIG.DND5E?.weaponProficiencies),
      tool: cfgList(CONFIG.DND5E?.toolTypes),
      focus: cfgList(CONFIG.DND5E?.focusTypes)
    }
  };
}

/** Builds a Trait advancement from `{grants, choices:[{count, pool}]}`, or null. */
export function buildTraitAdvancement(cfg) {
  const grants = Array.isArray(cfg?.grants) ? cfg.grants.map(String).filter(Boolean) : [];
  const choices = Array.isArray(cfg?.choices)
    ? cfg.choices
        .map((c) => ({
          count: Math.max(1, Math.min(Number(c?.count) || 1, 20)),
          pool: Array.isArray(c?.pool) ? c.pool.map(String).filter(Boolean) : []
        }))
        .filter((c) => c.pool.length)
    : [];
  if (!grants.length && !choices.length) return null;
  return {
    _id: foundry.utils.randomID(),
    type: "Trait",
    level: 0,
    configuration: { grants, choices, mode: "default", allowReplacements: false }
  };
}

/**
 * Creates a reusable world background item from the wizard's parameters.
 *
 * Runs on the GM client (players cannot create world items), so the module
 * itself draws the line: any player may author one — the same generosity the
 * character-creation wizard already extends — and the GM is told each time.
 */
export async function backgroundCreate(user, payload) {
  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("name is required");
  if (name.length > 100) throw new Error("name is too long");

  const abilityKeys = new Set(Object.keys(CONFIG.DND5E?.abilities ?? {}));
  const advancement = [];

  // Ability scores: the pool is the set the player may raise; everything else
  // is locked out so the ASI advancement offers exactly those abilities.
  const abil = payload?.abilities ?? {};
  const pool = Array.isArray(abil.pool) ? abil.pool.map(String).filter((a) => abilityKeys.has(a)) : [];
  if (pool.length) {
    advancement.push({
      _id: foundry.utils.randomID(),
      type: "AbilityScoreImprovement",
      level: 0,
      configuration: {
        points: Math.max(0, Math.min(Number(abil.points) || 0, 20)),
        cap: Math.max(1, Math.min(Number(abil.cap) || 2, 20)),
        fixed: {},
        locked: [...abilityKeys].filter((a) => !pool.includes(a))
      }
    });
  }

  for (const key of ["skills", "tools", "languages"]) {
    const adv = buildTraitAdvancement(payload?.[key]);
    if (adv) advancement.push(adv);
  }

  // Origin feat: granted through an ItemGrant advancement, verified to be a feat.
  const featUuid = payload?.feat?.uuid ? String(payload.feat.uuid) : "";
  if (featUuid) {
    const doc = await fromUuid(featUuid);
    if (!doc || doc.documentName !== "Item" || doc.type !== "feat") {
      throw new Error("Origin feat must be a feat item");
    }
    advancement.push({
      _id: foundry.utils.randomID(),
      type: "ItemGrant",
      level: 0,
      configuration: { items: [{ uuid: featUuid, optional: false }], optional: false, spell: null }
    });
  }

  // Starting equipment: the phone sends a nested AND/OR tree; dnd5e stores it
  // as a flat array whose children point at their parent by id.
  const startingEquipment = [];
  const flattenEquipment = (nodes, groupId) => {
    let sort = 0;
    for (const node of Array.isArray(nodes) ? nodes : []) {
      const type = String(node?.type ?? "");
      if (!EQUIPMENT_ENTRY_TYPES.has(type)) continue;
      const id = foundry.utils.randomID();
      const entry = { _id: id, group: groupId, sort: (sort += 100), type };
      if (Number(node?.count) > 1) entry.count = Number(node.count);
      if (node?.key) entry.key = String(node.key);
      if (node?.requiresProficiency) entry.requiresProficiency = true;
      startingEquipment.push(entry);
      if ((type === "AND" || type === "OR") && Array.isArray(node?.children)) {
        flattenEquipment(node.children, id);
      }
    }
  };
  flattenEquipment(payload?.equipment, null);

  const system = { advancement };
  const description = String(payload?.description ?? "").trim();
  if (description) system.description = { value: description };
  const identifier = String(payload?.identifier ?? "").trim();
  if (identifier) system.identifier = identifier.slugify ? identifier.slugify({ strict: true }) : identifier;
  if (startingEquipment.length) system.startingEquipment = startingEquipment;
  const wealth = String(payload?.wealth ?? "").trim();
  if (wealth) system.wealth = wealth;

  // Gold that comes *with* the item package (e.g. option A: items + 29 gp), as
  // opposed to `wealth`, dnd5e's "take gold instead" alternative (option B).
  // dnd5e's equipment tree has no currency entry, so this rides in a module flag
  // that our creation grant honours.
  const moduleFlags = { mobileBackground: { ownerUserId: user.id } };
  const equipmentCurrency = String(payload?.equipmentCurrency ?? "").trim();
  if (equipmentCurrency) moduleFlags.startingEquipmentCurrency = equipmentCurrency;

  // Optional icon, picked on the phone. Uploaded through the same asset-save
  // helper the token-image path uses; a world item has no owning actor, so it
  // gets its own per-user asset folder instead of an actor's.
  let img = null;
  if (payload?.imageBase64) {
    img = await uploadActorImage(user, null, payload.imageBase64, payload.mimeType, {
      requirePermission: false,
      maxLongSide: CHARACTER_IMAGE_MAX_LONG_SIDE,
      folderName: contentAssetFolder(user, "background")
    });
  }

  const levels = CONST.DOCUMENT_OWNERSHIP_LEVELS;
  const folder = await ensureContentFolder(user, "background");
  const created = await CONFIG.Item.documentClass.create({
    name,
    type: "background",
    system,
    folder: folder?.id ?? null,
    ownership: { default: levels.OBSERVER, [user.id]: levels.OWNER },
    flags: { [MODULE_ID]: moduleFlags },
    ...(img ? { img } : {})
  });
  if (!created) throw new Error("Background creation failed");
  await logWorldChange(user, `Created background "${created.name}"`);
  console.log(`[${MODULE_ID}] ${user.name} created background "${created.name}" (${created.id})`);
  return { itemId: created.id, name: created.name, uuid: created.uuid };
}

/** Reference data the race wizard builds its pickers from. */
