/**
 * Creates a reusable world feat item from the wizard's parameters: category
 * (subtype), free-text requirements and an optional ability-score
 * improvement and trait grants. Player-authorable and logged, exactly like
 * the race/background/class wizards.
 *
 * A feat is a plain `"feat"` Item whose `system.type.value` is also `"feat"`
 * (see feat.mjs's `ItemTypeField`) — the same document type class/racial
 * features use, distinguished only by `type.value`/`type.subtype`. The
 * existing feat pickers (`compendiumSearch`/`compendiumBrowse` with
 * `subtypes: ["feat"]`) filter on the Item's document type alone, so this is
 * automatically discoverable there without any picker changes.
 */
export async function featCreate(user, payload) {
  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("name is required");
  if (name.length > 100) throw new Error("name is too long");

  const abilityKeys = new Set(Object.keys(CONFIG.DND5E?.abilities ?? {}));
  const advancement = [];

  // Ability score improvement — optional; only added when the author picked a pool.
  const abil = payload?.abilities ?? {};
  const pool = Array.isArray(abil.pool) ? abil.pool.map(String).filter((a) => abilityKeys.has(a)) : [];
  if (pool.length) {
    advancement.push({
      _id: foundry.utils.randomID(),
      type: "AbilityScoreImprovement",
      level: 0,
      configuration: {
        points: Math.max(0, Math.min(Number(abil.points) || 0, 20)),
        cap: Math.max(1, Math.min(Number(abil.cap) || 2, 20)),
        fixed: {},
        locked: [...abilityKeys].filter((a) => !pool.includes(a))
      }
    });
  }

  for (const key of ["skills", "tools", "languages"]) {
    const adv = buildTraitAdvancement(payload?.[key]);
    if (adv) advancement.push(adv);
  }

  const system = { advancement };

  // Category (subtype) — general/origin/fightingStyle/epicBoon; general by default.
  const subtypes = CONFIG.DND5E?.featureTypes?.feat?.subtypes ?? {};
  const category = String(payload?.category ?? "").trim();
  system.type = { value: "feat", subtype: subtypes[category] ? category : "general" };

  // Free-text prerequisites (e.g. "Str 13", "Level 4+") — dnd5e's `requirements`
  // field, not the structured `prerequisites` block (which tracks item ids the
  // sheet itself proposes to repeat/require, not author-entered text).
  const requirements = String(payload?.requirements ?? "").trim();
  if (requirements) system.requirements = requirements;

  const description = String(payload?.description ?? "").trim();
  if (description) system.description = { value: description };
  const identifier = String(payload?.identifier ?? "").trim();
  if (identifier) system.identifier = identifier.slugify ? identifier.slugify({ strict: true }) : identifier;

  const levels = CONST.DOCUMENT_OWNERSHIP_LEVELS;
  const folder = await ensureContentFolder(user, "feat");
  const created = await CONFIG.Item.documentClass.create({
    name,
    type: "feat",
    system,
    folder: folder?.id ?? null,
    ownership: { default: levels.OBSERVER, [user.id]: levels.OWNER },
    flags: { [MODULE_ID]: { mobileFeat: { ownerUserId: user.id } } }
  });
  if (!created) throw new Error("Feat creation failed");
  await logWorldChange(user, `Created feat "${created.name}"`);
  console.log(`[${MODULE_ID}] ${user.name} created feat "${created.name}" (${created.id})`);
  return { itemId: created.id, name: created.name, uuid: created.uuid };
}

/* ------------------------------------------------------------------ *
 * Player homebrew library — Items/<player>/<content type>
 *
 * Authored content is filed under a per-player Item folder, one subfolder per
 * content type, so the "My content" screen can list a player's own races and
 * backgrounds and let them delete their own. Folders are matched by module flag,
 * not by name, so a renamed folder (or a language change) never orphans them.
 * ------------------------------------------------------------------ */

/** The dnd5e item type(s) a content-type key maps to. */
export function contentItemTypes(contentType) {
  if (contentType === "race") return [raceItemType()];
  if (contentType === "background") return ["background"];
  if (contentType === "class") return ["class"];
  if (contentType === "subclass") return ["subclass"];
  if (contentType === "feat") return ["feat"];
  return [];
}

/** Readable folder name for a content type, in the world's language. */
export function contentTypeFolderLabel(contentType) {
  // "feat" is special-cased ahead of the generic CONFIG lookup below: the Item
  // type "feat" is shared with class/racial features, whose CONFIG label
  // ("Feature") would otherwise win and mislabel the player's feat folder.
  if (contentType === "feat") return "Feats";
  const itemType = contentItemTypes(contentType)[0] ?? contentType;
  const label = CONFIG.Item?.typeLabels?.[itemType];
  if (label) {
    const localized = game.i18n.localize(label);
    if (localized && localized !== label) return localized;
  }
  if (contentType === "race") return "Races";
  if (contentType === "background") return "Backgrounds";
  if (contentType === "class") return "Classes";
  if (contentType === "subclass") return "Subclasses";
  return contentType;
}

export function findPlayerItemFolder(user) {
  return game.folders?.find(
    (f) => f.type === "Item" && !f.folder && bridgeFlag(f, "playerItemsOwner") === user.id
  ) ?? null;
}

export async function ensurePlayerItemFolder(user) {
  const existing = findPlayerItemFolder(user);
  if (existing) return existing;
  return Folder.create({
    name: String(user.name ?? "Player"),
    type: "Item",
    sorting: "a",
    flags: { [MODULE_ID]: { playerItemsOwner: user.id } }
  });
}

export function findContentFolder(user, contentType, parent) {
  const parentFolder = parent ?? findPlayerItemFolder(user);
  if (!parentFolder) return null;
  return game.folders?.find(
    (f) => f.type === "Item" && f.folder?.id === parentFolder.id
      && bridgeFlag(f, "contentType") === contentType
  ) ?? null;
}

/** The Items/<player>/<content type> folder, created (both levels) if absent. */
export async function ensureContentFolder(user, contentType) {
  const parent = await ensurePlayerItemFolder(user);
  const existing = findContentFolder(user, contentType, parent);
  if (existing) return existing;
  return Folder.create({
    name: contentTypeFolderLabel(contentType),
    type: "Item",
    folder: parent?.id ?? null,
    sorting: "a",
    flags: { [MODULE_ID]: { contentType, contentOwner: user.id } }
  });
}

/** The player's own authored items of one content type, from their folder. */
export function contentList(user, contentType) {
  const types = contentItemTypes(contentType);
  if (!types.length) throw new Error(`Unknown content type: ${contentType}`);
  const folder = findContentFolder(user, contentType);
  const items = [];
  if (folder) {
    for (const item of game.items ?? []) {
      if (item.folder?.id !== folder.id) continue;
      if (!types.includes(item.type)) continue;
      items.push({ itemId: item.id, name: item.name, uuid: item.uuid, img: routeAssetPath(item.img) });
    }
  }
  items.sort((a, b) => String(a.name).localeCompare(String(b.name)));
  return { items };
}

/** Deletes one of the player's own authored items. */
export async function contentDelete(user, itemId) {
  const id = String(itemId ?? "");
  const item = game.items?.get(id);
  if (!item) throw new Error("Item not found");
  if (!user.isGM && !item.testUserPermission(user, "OWNER")) throw new Error("not_yours");
  const name = item.name;
  await item.delete();
  await logWorldChange(user, `Deleted content "${name}"`);
  console.log(`[${MODULE_ID}] ${user.name} deleted content "${name}" (${id})`);
  return { deleted: true, itemId: id };
}

/**
 * A single shared journal for world-scoped events with no character to hang
 * them on — background authoring, and anything else the wizard does before a
 * sheet exists. GM-only, in the same folder as the per-character logs.
 */
export async function ensureCreationLog() {
  const folder = await ensureApprovalLogFolder();
  const existing = game.journal?.find(
    (entry) => entry.folder?.id === folder?.id && bridgeFlag(entry, "creationLog") === true
  );
  if (existing) return existing;
  return JournalEntry.create({
    name: "Character creation (mobile)",
    folder: folder?.id ?? null,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE },
    flags: { [MODULE_ID]: { creationLog: true } }
  });
}

/**
 * Logs a change that belongs to no single character: a page in the shared
 * creation log and a whispered line to the GMs. Best-effort, like
 * `logDirectChange` — a logging failure must not fail what already happened.
 */
export async function logWorldChange(user, summary) {
  const line = `${String(user?.name ?? "Player")}: ${summary}`;
  try {
    const journal = await ensureCreationLog();
    if (journal) {
      await journal.createEmbeddedDocuments("JournalEntryPage", [{
        name: `${new Date().toLocaleString()} — ${summary}`.slice(0, 120),
        type: "text",
        text: { content: `<p>${escapeHtml(line)}</p>`, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML }
      }]);
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] world-change log failed`, err);
  }
  try {
    const gmIds = game.users.filter((u) => u.isGM).map((u) => u.id);
    if (gmIds.length && typeof ChatMessage?.create === "function") {
      await ChatMessage.create({
        content: `<p><strong>Bag of Worlds</strong></p><p>${escapeHtml(line)}</p>`,
        whisper: gmIds,
        speaker: { alias: "Bag of Worlds" }
      });
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] world-change whisper failed`, err);
  }
}

export async function compendiumSearch(query, types, subtypes, limit, user = null) {
  const splitQuery = parseCompendiumSearchQuery(query);
  if (!splitQuery) return { results: [] };

  const nativeResult = await nativeCompendiumSearch(query, types, subtypes, limit, user);
  if (nativeResult.results.length > 0) return nativeResult;

  const spotlight =
    CONFIG?.SpotlightOmnisearch ??
    CONFIG?.SpotlightOmniseach ??
    globalThis.SpotlightOmnisearch ??
    null;
  const spotlightActive = game.modules.get("spotlight-omnisearch")?.active ?? false;

  console.log(
    `[${MODULE_ID}] compendium.search debug:`,
    {
      query: splitQuery.join(" "),
      nativeHits: nativeResult.results.length,
      hasConfigSpotlight: !!CONFIG?.SpotlightOmnisearch,
      indexLength: Array.isArray(spotlight?.INDEX) ? spotlight.INDEX.length : "not-array",
      hasRebuild: typeof spotlight?.rebuildIndex === "function",
      moduleEnabled: spotlightActive,
      executingUser: game.user?.name ?? null,
      isGmClient: !!game.user?.isGM
    }
  );

  if (!spotlightActive || !spotlight) {
    return nativeResult;
  }

  const spotlightResult = await spotlightCompendiumSearch(query, types, subtypes, limit, spotlight);
  if (spotlightResult.results.length > 0) return spotlightResult;

  console.log(`[${MODULE_ID}] compendium.search: native and Spotlight both returned 0 hits`);
  return nativeResult;
}

/**
 * DDB world packs sometimes store magic weapons as consumable/ammo with an
 * empty attack activity (no damage dice). Prefer a real weapon with the same
 * exact name from another pack when that pattern is detected.
 */
